import re, json, subprocess
# quick timings for the new shots
c = json.load(open("captions.json"))
W = c if isinstance(c, list) else c.get("words", [])
def find(q, start=0):
    ql=q.lower().split()
    for i in range(len(W)-len(ql)+1):
        if W[i]["startMs"] < start*1000: continue
        if all(W[i+k]["text"].strip().lower().strip(".,!?\"'()")==qk for k,qk in enumerate(ql))
